import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime dateTime;
  final double profitLoss;

  Transaction({required this.coinName, required this.dateTime, required this.profitLoss});
}

Map<String, double> calculateAverageProfitLoss(List<Transaction> transactions) {
  // Group transactions by coin name for aggregation
  final groupedTransactions = transactions.groupBy((transaction) => transaction.coinName);

  // Calculate average profit/loss per coin
  final avgProfitsAndLosses = <String, double>{};
  for (var (coin, transactionsGroup) in groupedTransactions.entries) {
    double totalProfitLoss = 0;
    transactionsGroup.forEach((transaction) => totalProfitLoss += transaction.profitLoss);
    avgProfitsAndLosses[coin] = totalProfitLoss / transactionsGroup.length;
  }

  return avgProfitsAndLosses;
}

List<MapEntry<String, double>> getTopCoins(Map<String, double> profitsAndLosses, int count, bool highestProfit) {
  // Sort by value (profit/loss) in descending order for highest profit, ascending for highest loss
  final sortedEntries = profitsAndLosses.entries.toList()
    ..sort((a, b) => highestProfit ? b.value.compareTo(a.value) : a.value.compareTo(b.value));
  return sortedEntries.sublist(0, count); 
}

Future<void> analyzeTransactions(List<Transaction> transactions) async {
  final avgProfitsAndLosses = calculateAverageProfitLoss(transactions);

  print("**Top 3 Coins with Highest Average Profit:**");
  final topProfitCoins = getTopCoins(avgProfitsAndLosses, 3, true);
  topProfitCoins.forEach((entry) => print('${entry.key}: ${entry.value.toStringAsFixed(2)}'));

  print("\n**Top 3 Coins with Highest Average Loss:**");
  final topLossCoins = getTopCoins(avgProfitsAndLosses, 3, false);
  topLossCoins.forEach((entry) => print('${entry.key}: ${entry.value.toStringAsFixed(2)}'));
}

