function swapAdjectives(sentence) {
  const words = sentence.split(' ');
  const adjectiveIndices = []; 
  for (let i = 0; i < words.length; i++) {
    // Simple heuristic: Assume words starting with capital letters are nouns (anchor points)
    if (words[i][0]toUpperCase() === words[i][0] && i > 0 && words[i - 1].toLowerCase() !== words[i].toLowerCase()) {
      adjectiveIndices.push(i - 1); // Likely adjective preceding the noun
    }
  }

  if (adjectiveIndices.length > 1) {  // Ensure at least two adjectives to swap
    const [firstIndex] = adjectiveIndices;
    const [secondIndex] = adjectiveIndices.slice(1); 
    [words[firstIndex], words[secondIndex]] = [words[secondIndex], words[firstIndex]]; 
    return words.join(' ');
  } else {
    return sentence; // Handle cases with few or no clear adjective pairs
  }
}

// Example usage:
const originalSentence = "Beautiful green trees are in the park";
const reorderedSentence = swapAdjectives(originalSentence);
console.log(reorderedSentence); // Output: Green beautiful trees are in the park 
```

