#include <iostream>
#include <limits>

using namespace std;

// Recursive Fibonacci function
int fibonacci(int a, int b, int n) {
    if (n == 0) return a;  // Base case: return the first element
    if (n == 1) return b;  // Base case: return the second element
    return fibonacci(b, a + b, n - 1); // Recursive step
}

int main() {
    int start1, start2, count;

    cout << "Enter the first two Fibonacci numbers: ";
    while (!(cin >> start1 >> start2)) {  // Input validation for numeric values
        cout << "Invalid input. Please enter integers: ";
        cin.clear();  // Clear error flags
        cin.ignore(numeric_limits<streamsize>::max(), '\n'); // Discard invalid input
    }
    if (start1 < 0 || start2 < 0) {  // Handle negative input
        cout << "Error: Starting numbers must be non-negative.\n";
        return 1; // Indicate an error
    }

    cout << "Enter the desired sequence length: ";
    while (!(cin >> count) || count <= 0) {  // Validate count as positive integer
        cout << "Invalid input. Enter a positive integer: ";
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
    }

    cout << "Fibonacci Sequence (starting with " << start1 << ", " << start2 << "): ";
    for (int i = 0; i < count; ++i) {
        cout << fibonacci(start1, start2, i) << ", ";
        // Update start1 and start2 for the next iteration (implicit in recursive calls)
    }
    cout << endl; // Final newline

    return 0; 
}
